draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // drawing a symbolic object: a combination lock with the numbers 1, 1, 2, and 9
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('11', W / 2 - 30 + 20 * Math.sin(t), H / 2 - 20);
  ctx.fillText('29', W / 2 + 10 + 20 * Math.cos(t), H / 2 + 20);
  ctx.beginPath();
  ctx.arc(W / 2 - 30 + 20 * Math.sin(t), H / 2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 10 + 20 * Math.cos(t), H / 2 + 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
